from taf.gnb.oam.coam.vdu.releases.vduoam25r2 import vDuOAM25R2
from taf.gnb.oam.coam.vdu.schemas.asm.cell_status_basic_cell import (
    CellsStatusBasicCellASMV1,
)
from taf.gnb.oam.coam.vdu.schemas.cm_licensed.plan_activation_operation_status_v1 import (
    PlanActivateOperationStatusLICENSEDV1,
)
from taf.gnb.oam.coam.vdu.utilities.use_m2m_parser import enforce_use_m2m_type


class vDuOAM25R3(vDuOAM25R2):
    @enforce_use_m2m_type
    def start_rf_diagnostic_test(self, nr_cell_id=-1, rx_antenna_rssi_high_threshold=-30,
                                 rx_antenna_rssi_low_threshold=-110, tx_antenna_vswr_high_threshold=3,
                                 rx_antenna_rtwp_high_threshold=0, rx_antenna_rtwp_low_threshold=0, timeout=60, **kwargs):
        self.cp_config_licensed.start_rf_diagnostic_test(
            nr_cell_id=nr_cell_id,
            rx_antenna_rssi_high_threshold=rx_antenna_rssi_high_threshold,
            rx_antenna_rssi_low_threshold=rx_antenna_rssi_low_threshold,
            tx_antenna_vswr_high_threshold=tx_antenna_vswr_high_threshold,
            rx_antenna_rtwp_high_threshold=rx_antenna_rtwp_high_threshold,
            rx_antenna_rtwp_low_threshold=rx_antenna_rtwp_low_threshold,
            timeout=timeout)

    def perform_parameter_recommissioning(self, dist_name, parameter, operation, value, should_activate=True, timeout=300):
        return self.asm_licensed.perform_parameter_recommissioning(dist_name=dist_name,
                                                                   parameter=parameter,
                                                                   operation=operation,
                                                                   value=value,
                                                                   should_activate=should_activate,
                                                                   timeout=timeout,
                                                                   nidd_info=self.get_nidd())

    def perform_object_recommissioning(self, dist_name, parameter, operation, should_activate=True, timeout=300):
        return self.asm_licensed.perform_object_recommissioning(dist_name=dist_name,
                                                                parameter=parameter,
                                                                operation=operation,
                                                                should_activate=should_activate,
                                                                timeout=timeout,
                                                                nidd_info=self.get_nidd())

    def start_diagnostic_check(self, allow_service_impact=False, wait_for_completion=False, timeout=300):
        return self.asm_licensed.start_diagnostic_check(allow_service_impact=allow_service_impact,
                                                        wait_for_completion=wait_for_completion, timeout=timeout)

    def get_diagnostic_check_status(self, operation_id, timeout=30):
        return self.asm_licensed.get_diagnostic_check_status(operation_id=operation_id, timeout=timeout)

    def get_diagnostic_check_reports(self, timeout=30):
        return self.asm_licensed.get_diagnostic_check_reports(timeout=timeout)

    def get_vnf_and_rmod_checkpoints(self, timeout=30):
        return self.asm_v1.get_vnf_and_rmod_checkpoints(timeout=timeout)

    def start_customized_diagnostic_check(self, vnf_checkpoint_ids, rmod_checkpoint_ids, wait_for_completion=False,
                                          timeout=300):
        return self.asm_v1.start_customized_diagnostic_check(vnf_checkpoint_ids=vnf_checkpoint_ids,
                                                          rmod_checkpoint_ids=rmod_checkpoint_ids,
                                                          wait_for_completion=wait_for_completion,
                                                          timeout=timeout)

    def get_customized_diagnostic_check_status(self, operation_id, timeout=30):
        return self.asm_v1.get_customized_diagnostic_check_status(operation_id=operation_id, timeout=timeout)

    @enforce_use_m2m_type
    def get_scf(self, timeout=30, include_runtime_data=False, include_auto_config_data=True, use_m2m=True):
        if use_m2m:
            return self.cm_licensed.get_current_plan_content(include_runtime_data=include_runtime_data,
                                                             include_auto_config_data=include_auto_config_data,
                                                             timeout=timeout)
        else:
            return self.cm.get_current_plan_content(include_runtime_data=include_runtime_data,
                                                    include_auto_config_data=include_auto_config_data,
                                                    timeout=timeout)

    def get_pod_sync_status(self, pod_id, timeout=30):
        return self.agent_v1.get_pod_sync_status(pod_id=pod_id, timeout=timeout)

    def start_antenna_monitoring(self, antennas, timeout=30, wait_for_completion=False):
        return self.fh_licensed_v1.start_antenna_monitoring(antennas=antennas, timeout=timeout,
                                                            wait_for_completion=wait_for_completion)

    def get_antenna_monitoring_status(self, monitor_id, timeout=30):
        return self.fh_licensed_v1.get_antenna_monitoring_status(monitor_id=monitor_id, timeout=timeout)

    def stop_antenna_monitoring(self, monitor_id, timeout=30):
        return self.fh_licensed_v1.stop_antenna_monitoring(monitor_id=monitor_id, timeout=timeout)

    def get_antenna_monitoring_results(self, monitor_id, timeout=30):
        return self.fh_licensed_v1.get_antenna_monitoring_results(monitor_id=monitor_id, timeout=timeout)

    @enforce_use_m2m_type
    def get_local_snapshot(self, directory, request_timeout, operation_timeout, use_m2m=True, compressed_or_not=False,
                           coverage='full', filter_regx=None):
        if use_m2m:
            return self.asm_licensed.get_local_snapshot(directory=directory, request_timeout=request_timeout,
                                                        operation_timeout=operation_timeout,
                                                        compressed=compressed_or_not, coverage=coverage,
                                                        filter_regx=filter_regx)
        else:
            return self.asm_v1.get_local_snapshot(directory=directory, request_timeout=request_timeout,
                                                  operation_timeout=operation_timeout, compressed=compressed_or_not,
                                                  coverage=coverage, filter_regx=filter_regx)

    @enforce_use_m2m_type
    def trigger_local_snapshot(self, request_timeout=30, operation_timeout=600, use_m2m=True, coverage='full', filter_regx=None):
        if use_m2m:
            return self.asm_licensed.trigger_local_snapshot(request_timeout=request_timeout,
                                                            coverage=coverage,
                                                            filter_regx=filter_regx)
        else:
            return self.asm_v1.trigger_local_snapshot(request_timeout=request_timeout, coverage=coverage, filter_regx=filter_regx)

    @enforce_use_m2m_type
    def activate_pre_activated_plan(self, plan_id, timeout=30, use_m2m=True):
        if use_m2m:
            return self.em_service_licensed_v1.activate_pre_activated_plan(plan_id=plan_id, timeout=timeout)
        else:
            return self.cm.activate_pre_activated_plan(plan_id=plan_id, timeout=timeout)

    @enforce_use_m2m_type
    def get_activated_operation_status(self, plan_id, operation_id, timeout=30, use_m2m=True):
        if use_m2m:
            return self.em_service_licensed_v1.get_activated_operation_status(plan_id=plan_id, operation_id=operation_id,
                                                                              timeout=timeout)
        else:
            return self.cm.get_activated_operation_status(plan_id=plan_id, operation_id=operation_id, timeout=timeout)

    @enforce_use_m2m_type
    def get_activated_operation_detail_status(self, plan_id, operation_id, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            res = self.em_service_licensed_v1.get_activated_operation_detail_status(plan_id=plan_id, operation_id=operation_id,
                                                                                    timeout=timeout)
        else:
            res = self.cm.get_activated_operation_detail_status(plan_id=plan_id, operation_id=operation_id,
                                                                timeout=timeout)
        return res if raw else PlanActivateOperationStatusLICENSEDV1.from_object_dict(res)

    def get_antenna_monitoring_result_file(self, directory, timeout=30):
        return self.fh_licensed_v1.get_antenna_monitoring_result_file(directory=directory, timeout=timeout)

    @enforce_use_m2m_type
    def get_vdu_cells_status(self, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            cell_diff = self.asm_licensed.get_vdu_cells_status(timeout=timeout)
        else:
            cell_diff = self.asm_v1.get_vdu_cells_status(timeout=timeout)

        if raw:
            return cell_diff['created']
        else:
            cells_statuses = []
            created_cells = cell_diff['created']

            if len(created_cells) > 0:
                for cell in created_cells:
                    statuses = CellsStatusBasicCellASMV1.from_object_dict(cell).to_dict()
                    # To keep the compatibility there is a need to elevate content of the key basic_cell one level up.
                    # So we want to get from:
                    # { 'key1': 'value1', 'key2': 'value2', 'basic_cell':{ 'key3': 'value3', 'key4': 'value4', }, }
                    # to:
                    # { 'key1': 'value1', 'key2': 'value2', 'key3': 'value3', 'key4': 'value4', }
                    basic_cell_status = statuses.pop('basic_cell')
                    statuses.update(basic_cell_status)
                    cells_statuses.append(statuses)
            return cells_statuses
